// Si esta ejecucion no era la del ultimo mensaje, no llegan filas y se corta.
const filas = $input.all().map(i => i.json).filter(j => j && j.id && j.content);
if (filas.length === 0) return [];
filas.sort((a, b) => Number(a.id) - Number(b.id));
const chat_input = filas.map(f => String(f.content).trim()).filter(Boolean).join('\n');
return [{ json: { chat_input } }];

const lead = $('Get Lead').first().json || {};
const contactos = (lead._embedded && lead._embedded.contacts) || [];
const principal = contactos.find(c => c.is_main) || contactos[0];
const contact_id = (principal && principal.id) || Number($('Set Campos Mensaje').first().json.contact_id) || null;
let output = String($json.output || '').trim();
if (!output) return [];
// Kommo/WhatsApp no renderizan markdown de titulos ni negritas dobles.
output = output.replace(/\*\*(.+?)\*\*/g, '*$1*').replace(/^#+\s*/gm, '');
return [{ json: { output, contact_id } }];
